LOCK TABLES `roles` WRITE;
INSERT INTO `roles` (`id`, `name`, `description`, `is_system`, `created_at`, `updated_at`) VALUES (1,'Admin','Quản trị hệ thống: người dùng, phòng ban, danh mục và phân quyền. Không thuộc phòng ban hay dự án nào.',1,'2026-10-08 10:28:28','2026-10-08 10:28:28'),(2,'CEO','Ban điều hành: xem toàn bộ dự án, task, logwork và dashboard công ty',1,'2026-10-08 10:28:28','2026-10-08 10:28:28'),(3,'Project Manager','Quản lý dự án mình phụ trách: thành viên, sprint, task, duyệt logwork',1,'2026-10-08 10:28:28','2026-10-08 10:28:28'),(4,'Team Leader','Điều phối nhóm trong dự án: giao việc, sửa task, duyệt logwork',1,'2026-10-08 10:28:28','2026-10-08 10:28:28'),(5,'Employee','Nhân viên: xem dự án mình tham gia, quản lý task và logwork của bản thân',1,'2026-10-08 10:28:28','2026-10-08 10:28:28'),(6,'Intern','Thực tập sinh: chỉ thấy task được giao và ghi logwork của mình',1,'2026-10-08 10:28:28','2026-10-08 10:28:28');
UNLOCK TABLES;

